      `CLAIM_SETTLED sheet=${sheet} by=vic person=Ada amount=20.00 date=2026-03-10`,
      `CLAIM_VOIDED sheet=${sheet} by=vic person=Ada amount=30.00 date=2026-03-10`
    ]);
  });
