-- The sheet's rate for each grade: a percent with two decimals. A grade with no row has no rate.
CREATE TABLE rate (
    sheet VARCHAR(200)  NOT NULL,
    grade VARCHAR(1)    NOT NULL,
    pct   DECIMAL(9, 2) NOT NULL,
    PRIMARY KEY (sheet, grade)
);
package net.officefloor.hq.app.person;

import java.util.List;
import org.springframework.dao.DuplicateKeyException;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.stereotype.Repository;

/** The people kept per sheet. */
@Repository
public class People {

    private static final RowMapper<Person> ROW = (rs, i) -> new Person(rs.getLong("id"), rs.getString("name"),
            rs.getString("grade"));

    private final JdbcTemplate jdbc;

    public People(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** Everyone on the sheet, in the order they were added. */
    public List<Person> list(String sheet) {
        return jdbc.query("SELECT id, name, grade FROM person WHERE sheet = ? ORDER BY id", ROW, sheet);
    }

    public Person find(String sheet, long id) {
        List<Person> found = jdbc.query("SELECT id, name, grade FROM person WHERE sheet = ? AND id = ?", ROW,
                sheet, id);
        return found.isEmpty() ? null : found.get(0);
    }

    /** Whether someone on the sheet other than {@code except} has this name, ignoring case. */
    private boolean nameTaken(String sheet, String name, Long except) {
        Integer taken = jdbc.queryForObject(
                "SELECT COUNT(*) FROM person WHERE sheet = ? AND name_key = LOWER(?) AND (? IS NULL OR id <> ?)",
                Integer.class, sheet, name, except, except);
#!/usr/bin/env bash
# Build, start the whole app, run the Playwright specs present in e2e/specs, then stop.
set -euo pipefail
cd "$(dirname "$0")/.."

export PORT="${PORT:-3000}"
export BASE_URL="http://localhost:${PORT}"
# Known audit file, shared by the app (bin/start) and the specs (support/audit.ts). Absolute.
export AUDIT_FILE="${AUDIT_FILE:-$PWD/.run/audit.log}"

# Refuse to run against a server that is not ours: an app left running on $PORT (an earlier
# bin/start that was never stopped, another sandbox) would take the tests and fail them all.
if curl -fsS "${BASE_URL}/actuator/health" >/dev/null 2>&1; then
  echo "bin/e2e: something is already serving on port ${PORT}; stop it (bin/stop) or set PORT to a free port" >&2
  exit 2
fi

bin/build
bin/start
cleanup() { bin/stop || true; }
trap cleanup EXIT

# Wait for readiness (Actuator health), then run the Playwright specs against BASE_URL. A loaded
# machine can take minutes to bring the JVM up; running the specs before it is ready fails every
# one of them for no reason, so wait long and fail loudly rather than run against nothing.
ready=0
for i in $(seq 1 300); do
  if curl -fsS "${BASE_URL}/actuator/health" >/dev/null 2>&1; then ready=1; break; fi
  sleep 1
done

